INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14401, 'Psalms 90:11', 'Psalms', 90, 11, '&nbsp;ستا د غصې زور چا ته معلوم دے؟ ځکه چې ستا غصه دومره لويه ده څومره چې ستا نه يره پکار ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14402, 'Psalms 90:12', 'Psalms', 90, 12, '&nbsp;تۀ مونږ د خپل ژوند د لنډوالى نه خبر کړه، ترڅو چې مونږ په عقلمندۍ سره ژوند وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14403, 'Psalms 90:13', 'Psalms', 90, 13, '&nbsp;اے مالِکه خُدايه، راشه، دا به ترڅو پورې وى؟ په خپل خِدمتګارانو باندې رحم وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14404, 'Psalms 90:14', 'Psalms', 90, 14, '&nbsp;مونږ دې په خپله ابدى مينه باندې په سحر کښې ماړۀ کړه، ترڅو چې مونږ د خوشحالۍ سندرې ووايو او ټول عمر خوشحاله شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14405, 'Psalms 90:15', 'Psalms', 90, 15, '&nbsp;څومره چې په مونږ سخته وه مونږ ته دومره خوشحالى راکړه، چې څومره عمر زمونږ په غم وو دومره خوشحالى راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14406, 'Psalms 90:16', 'Psalms', 90, 16, '&nbsp;ستا ټول کارونه دې ستا خِدمتګارانو ته ښکاره شى، ستا جلال دې پاکه خُدايه د دوئ بچو ته ښکاره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14407, 'Psalms 90:17', 'Psalms', 90, 17, '&nbsp;اے مالِکه خُدايه، پاکه خُدايه، ستا جلال دې په مونږ رانازل شى، زمونږ د لاسونو کارونه مونږ ته مضبوط کړه او زمونږ د لاسونو کارونو له کاميابى ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14408, 'Psalms 91:1', 'Psalms', 91, 1, '&nbsp;هغه څوک چې د خُدائ تعالىٰ په پناه کښې اوسيږى، هغه به د قادر خُدائ د سورى لاندې په امان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14409, 'Psalms 91:2', 'Psalms', 91, 2, '&nbsp;زۀ به داسې وايم چې، ”مالِک خُدائ زما پناه او هم زما قلعه ده، هم هغه زما خُدائ پاک دے په چا چې توکل کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14410, 'Psalms 91:3', 'Psalms', 91, 3, '&nbsp;بې‌شکه هغه به تاسو د ښکاريانو د دامونو نه خلاص کړى او هغه به تاسو د سختو بيماريانو نه بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14411, 'Psalms 91:4', 'Psalms', 91, 4, '&nbsp;په خپلو بڼو به دې پټ کړى او تۀ به د هغۀ د وزرونو لاندې پناه ومومې. د هغۀ وفادارى به دې ډال او ستا د حفاظت دېوال وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14412, 'Psalms 91:5', 'Psalms', 91, 5, '&nbsp;تۀ به د شپې د دهشت نه نۀ يرېږې، او نۀ به تۀ د ورځې د غشى نه يرېږې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14413, 'Psalms 91:6', 'Psalms', 91, 6, '&nbsp;او نۀ به د هغې وبا نه يرېږې چې په تيارۀ کښې راځى، او نۀ به د هغې تباهۍ نه چې په رڼا ورځ کښې راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14414, 'Psalms 91:7', 'Psalms', 91, 7, '&nbsp;زر کسان به دې په خوا کښې او لس زره به دې ښى لاس ته راوغورزيږى، خو تا ته به څۀ نقصان نۀ رسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14415, 'Psalms 91:8', 'Psalms', 91, 8, '&nbsp;کۀ تۀ صرف سترګې کولاو کړې، نو وبه ګورې چې بدعملو ته څنګه سزا ورکولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14416, 'Psalms 91:9', 'Psalms', 91, 9, '&nbsp;کۀ چرې تۀ قادر مطلق خُدائ خپل د پناه ځائ جوړ کړې، او کۀ تۀ خُدائ تعالىٰ خپل د اوسېدو ځائ جوړ کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14417, 'Psalms 91:10', 'Psalms', 91, 10, '&nbsp;نو هيڅ قِسمه نقصان به تا ته ونۀ رسيږى، او هيڅ قسمه افت به ستا خېمې ته نۀ رانزدې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14418, 'Psalms 91:11', 'Psalms', 91, 11, '&nbsp;ځکه چې هغه به ستا په حقله خپلو فرښتو له حُکم ورکړى، تۀ چې چرته هم ځې دوئ به ستا حفاظت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14419, 'Psalms 91:12', 'Psalms', 91, 12, '&nbsp;هغوئ به دې په خپلو لاسونو کښې پورته کړى هسې نه چې په کاڼى تيندک وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14420, 'Psalms 91:13', 'Psalms', 91, 13, '&nbsp;تۀ به په ازمرى او مار باندې پښې ږدې، تۀ به ځوان زمرے او اژدها د پښو لاندې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14421, 'Psalms 91:14', 'Psalms', 91, 14, '&nbsp;مالِک خُدائ فرمائى، ”ځکه چې دے ما سره مينه کوى زۀ به يې بچ کړم، هغه زما په نامه يقين لرى زۀ به امان ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14422, 'Psalms 91:15', 'Psalms', 91, 15, '&nbsp;هغه به له ما نه سوال وکړى او زۀ به هغه قبول کړم. په سخته کښې به زۀ د هغۀ سره يم زۀ به هغه بچ کړم، او عزت به هغۀ ته ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14423, 'Psalms 91:16', 'Psalms', 91, 16, '&nbsp;زۀ به هغه په ډېر ژوند او عمر باندې موړ کړم، او زۀ به خپل خلاصون هغۀ ته وښايم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14424, 'Psalms 92:1', 'Psalms', 92, 1, '&nbsp;دا ښۀ خبره ده چې ستا ثناء صِفت وکړُو مالِکه خُدايه، او په حمدونو کښې ستا د نوم ستائينه وکړُو خُدائ تعالىٰ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14425, 'Psalms 92:2', 'Psalms', 92, 2, '&nbsp;هر سحر چې ستا ابدى مينه ياده کړُو، او په شپه کښې ستا وفادارى ياده کړُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14426, 'Psalms 92:3', 'Psalms', 92, 3, '&nbsp;د بينجو په لس تاريزه ساز کښې، او د رباب په سازونو کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14427, 'Psalms 92:4', 'Psalms', 92, 4, '&nbsp;ځکه چې تا زۀ په خپلو کارونو خوشحاله کړے يم. ستا د لاسونو په کارونو زۀ د خوشحالۍ سندرې وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14428, 'Psalms 92:5', 'Psalms', 92, 5, '&nbsp;اے مالِکه خُدايه، ستا کارونه څومره لوئ دى، او ستا سوچونه څومره ژور دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14429, 'Psalms 92:6', 'Psalms', 92, 6, '&nbsp;بې‌احساسه خلق په دې نۀ پوهيږى، او کم عقل په دې نۀ پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14430, 'Psalms 92:7', 'Psalms', 92, 7, '&nbsp;بدکاران کۀ څۀ هم لکه د واښو هسې راټوکيږى، او ټول بدکاران کۀ اوچتيږى، خو بيا هم دوئ به د تل دپاره تباه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14431, 'Psalms 92:8', 'Psalms', 92, 8, '&nbsp;خو تۀ، اے مالِکه خُدايه، اوچت يې تر ابده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14432, 'Psalms 92:9', 'Psalms', 92, 9, '&nbsp;په يقين سره ستا دشمنان به مالِکه خُدايه تباه شى، او ټول بدکاران به تالا والا شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14433, 'Psalms 92:10', 'Psalms', 92, 10, '&nbsp;لکه د ځنګلى غوَيى په شان تا زما ښکر اوچت کړے دے. په ښۀ تېلو باندې دې غوړ کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14434, 'Psalms 92:11', 'Psalms', 92, 11, '&nbsp;زما سترګو زما د دشمنانو شکست وليدلو، زما غوږونو زما د بدکارو دشمنانو وريتې چغې واورېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14435, 'Psalms 92:12', 'Psalms', 92, 12, '&nbsp;صادقان به لکه د کجورې د ونې په شان ترقى کوى، او دوئ به لکه د لبنان د دِيار غوندې لوئيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14436, 'Psalms 92:13', 'Psalms', 92, 13, '&nbsp;هغه چې د مالِک خُدائ په کور کښې کَرلے شوى وى، دوئ به زمونږ د خُدائ پاک په دربار کښې غوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14437, 'Psalms 92:14', 'Psalms', 92, 14, '&nbsp;تر دې چې به په زوړ عمر کښې هم مېوه نيسى، دوئ به هر وخت تازه او شنۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14438, 'Psalms 92:15', 'Psalms', 92, 15, '&nbsp;نو داسې به دوئ دا ښکاره کړى چې مالِک خُدائ رښتينے دے، هغه زما د ‎پناه ګټ دے او په دۀ کښې څۀ بې‌اِنصافى نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14439, 'Psalms 93:1', 'Psalms', 93, 1, '&nbsp;مالِک خُدائ بادشاهى کوى او د عزت چُوغه يې اغوستې ده، او د هغۀ لاسونه زورَور دى مالِک خُدائ د شان او شوکت چُوغه اغوستې ده. دُنيا نۀ شى خوځېدے هغۀ مضبوطه جوړه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14440, 'Psalms 93:2', 'Psalms', 93, 2, '&nbsp;ستا تخت د پخوا نه قائم شوے دے، او ستا ذات د ازل نه موجود دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14441, 'Psalms 93:3', 'Psalms', 93, 3, '&nbsp;اے مالِکه خُدايه، سمندرونه راپاڅېدلى دى، سيندونو شورونه جوړ کړى دى، سيندونو خپلې ناترسې چپې راپورته کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14442, 'Psalms 93:4', 'Psalms', 93, 4, '&nbsp;مالِک خُدائ د ډېرو اوبو د شور نه هم زورَور دے، او د سمندر د موجونو نه هم زورَور دے. بره مالِک خُدائ د دې ټولو نه زورَور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14443, 'Psalms 93:5', 'Psalms', 93, 5, '&nbsp;ستا اصُول او قانون قائم دے. او پاکوالے ستا د کور ښائست دے، تر ابده پورې اے مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14444, 'Psalms 94:1', 'Psalms', 94, 1, '&nbsp;اے مالِکه خُدايه، بدله اخستونکى، پاکه خُدايه، بدله اخستونکى پاکه خُدايه خپل جلال دې وځلوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14445, 'Psalms 94:2', 'Psalms', 94, 2, '&nbsp;اے د دُنيا منصفه، راپاڅه، مغرورانو له د دوئ د عملونو په مطابق سزا ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14446, 'Psalms 94:3', 'Psalms', 94, 3, '&nbsp;ترڅو به بدکاران، مالِکه خُدايه، ترڅو به بدکاران خوشحالى کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14447, 'Psalms 94:4', 'Psalms', 94, 4, '&nbsp;هغوئ ټولې خبرې د کبر او د غرور کوى، ټول بدکاران ډيرې لافې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14448, 'Psalms 94:5', 'Psalms', 94, 5, '&nbsp;اے مالِکه خُدايه، دوئ ستا خلق تباه کوى، هغوئ ستا په ميراث باندې ظلمونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14449, 'Psalms 94:6', 'Psalms', 94, 6, '&nbsp;هغوئ مسافر او کونډې قتلوى، هغوئ يتيمان وژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14450, 'Psalms 94:7', 'Psalms', 94, 7, '&nbsp;دوئ وائى چې، ”مالِک خُدائ دا نۀ ګورى، او د يعقوب خُدائ پاک پام نۀ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14451, 'Psalms 94:8', 'Psalms', 94, 8, '&nbsp;اے د قوم بې‌عقله خلقو ځان خبر کړئ، اے ناپوهه خلقو تاسو به کله خپل ځان هوښياروئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14452, 'Psalms 94:9', 'Psalms', 94, 9, '&nbsp;هغۀ چې مونږ له يې غوږونه راکړل خپله اورېدے نۀ شى څۀ؟ هغۀ چې مونږ له يې سترګې راکړې نو په خپله ليدلے نۀ شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14453, 'Psalms 94:10', 'Psalms', 94, 10, '&nbsp;څوک چې قومونه سموى نو سزا نۀ شى ورکولے څۀ؟ څوک چې انسان ته پوهه ورکوى په خپله به ناپوهه وى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14454, 'Psalms 94:11', 'Psalms', 94, 11, '&nbsp;مالِک خُدائ د انسان په سوچونو باندې پوهه دے، چې دا ټوله تشه هوا او بې‌فائدې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14455, 'Psalms 94:12', 'Psalms', 94, 12, '&nbsp;بختور دے هغه څوک چې تۀ يې تنبيه کوې مالِکه خُدايه، بختور دے هغه چا له چې تۀ د خپل قانون نه سبق ورکوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14456, 'Psalms 94:13', 'Psalms', 94, 13, '&nbsp;تۀ هغۀ ته په سختو ورځو کښې آرام ورکوې، ترڅو چې بدعملو له کنده کنستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14457, 'Psalms 94:14', 'Psalms', 94, 14, '&nbsp;مالِک خُدائ به خپل خلق نۀ رد کوى، او هغه به خپل ميراث نۀ هېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14458, 'Psalms 94:15', 'Psalms', 94, 15, '&nbsp;يو ځل بيا به عدالت د صداقت په مطابق وشى، او ټول صادقان به يې پيروى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14459, 'Psalms 94:16', 'Psalms', 94, 16, '&nbsp;څوک به ما سره د بدکارانو خلاف راپاڅى؟ او څوک به زما دپاره د بدعملو خلاف ودريږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14460, 'Psalms 94:17', 'Psalms', 94, 17, '&nbsp;کۀ مالِک خُدائ زما مددګار نۀ وے، نو اوس به زۀ د مرګ په خاموشۍ کښې اوسېدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14461, 'Psalms 94:18', 'Psalms', 94, 18, '&nbsp;نو کله چې ما ووئيل چې، ”زما پښې ښوئيږى،“ نو ستا ابدى مينې زما مدد وکړو مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14462, 'Psalms 94:19', 'Psalms', 94, 19, '&nbsp;کله چې زما د زړۀ بې‌قرارى ډېره زياته شوه، نو ستا تسلۍ زما روح ته خوشحالى راوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14463, 'Psalms 94:20', 'Psalms', 94, 20, '&nbsp;بې‌اِنصافه مشران تا سره ملګرتيا کولے شى، چې د قانون په نوم لا قانونيت جوړوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14464, 'Psalms 94:21', 'Psalms', 94, 21, '&nbsp;هغوئ د صادقانو خلاف ډله جوړوى، او بې‌ګناه خلق قاتل ګرځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14465, 'Psalms 94:22', 'Psalms', 94, 22, '&nbsp;خو مالِک خُدائ زما پناه ګاه ده، او خُدائ پاک زما ګټ دے په چا کښې چې زۀ پناه اخلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14466, 'Psalms 94:23', 'Psalms', 94, 23, '&nbsp;هغه به دوئ ته د دوئ د ګناه په وجه سزا ورکړى. او د دوئ د شرارت په وجه به يې تباه کړى، مالِک خُدائ زمونږ خُدائ پاک به يې ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14467, 'Psalms 95:1', 'Psalms', 95, 1, '&nbsp;راځئ، چې مالِک خُدائ ته حمد و ثناء ووايو، راځئ چې د خوشحالۍ نعرې زمونږ د خلاصون ګټ ته ووايو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14468, 'Psalms 95:2', 'Psalms', 95, 2, '&nbsp;راځئ چې په شُکر ګزارۍ سره د هغۀ حضور ته راشو، او د هغۀ د حمد‌و‌ثناء سندرې ووايو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14469, 'Psalms 95:3', 'Psalms', 95, 3, '&nbsp;ځکه چې مالِک خُدائ لوئ خُدائ پاک دے، هغه د ټولو معبودانو نه زورَور او لوئ بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14470, 'Psalms 95:4', 'Psalms', 95, 4, '&nbsp;د زمکې ژوروالے د هغۀ په لاس کښې دے، د غرونو ټولې څُوکې د هغۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14471, 'Psalms 95:5', 'Psalms', 95, 5, '&nbsp;سمندرونه د هغۀ دى ځکه چې هغۀ جوړ کړى دى. او د هغۀ لاسونو اوچه زمکه پېدا کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14472, 'Psalms 95:6', 'Psalms', 95, 6, '&nbsp;راځئ، چې عبادت او سجده وکړُو، راځئ، چې د مالِک خُدائ او د خپل خالق په حضور کښې په سجده شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14473, 'Psalms 95:7', 'Psalms', 95, 7, '&nbsp;ځکه چې هغه زمونږ خُدائ پاک دے، او مونږ د هغۀ د سادين خلق يُو، او د هغۀ رمه يُو د چا چې هغه خيال ساتى. کۀ تاسو نن ورځ د هغۀ آواز واورئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14474, 'Psalms 95:8', 'Psalms', 95, 8, '&nbsp;نو خپل زړونه هغه شان مۀ سختوئ لکه څنګه چې تاسو په مريبه کښې سخت کړى وُو، او لکه څنګه چې تاسو د مسه په بيابان کښې سخت کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14475, 'Psalms 95:9', 'Psalms', 95, 9, '&nbsp;چرته چې ستاسو پلار نيکونو زما جاج او آزمېښت وکړو د دې باوجود چې هغوئ هر څۀ وليدل چې ما ورله څۀ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14476, 'Psalms 95:10', 'Psalms', 95, 10, '&nbsp;تر څلوېښتو کالو پورې هغه نسل ته غصه وم، ما ووئيل چې، ”دا هغه خلق دى چې زړونه يې ما نه لرى شوى دى، او دوئ زما لارې ونۀ پېژندلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14477, 'Psalms 95:11', 'Psalms', 95, 11, '&nbsp;نو ما په خپله غصه کښې قسم وخوړلو چې، ”کله به هم هغوئ زما په آرام کښې داخل نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14478, 'Psalms 96:1', 'Psalms', 96, 1, '&nbsp;مالِک خُدائ ته يوه نوې سندره ووايئ، اے ټولې دُنيا مالِک خُدائ ته سرود ووايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14479, 'Psalms 96:2', 'Psalms', 96, 2, '&nbsp;مالِک خُدائ ته سرود ووايئ او د هغۀ د نوم ثناء ووايئ، او د هغۀ خلاصون هره ورځ بيان کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14480, 'Psalms 96:3', 'Psalms', 96, 3, '&nbsp;په قومونو کښې د هغۀ د جلال اعلان وکړه، د دُنيا په ټولو خلقو کښې د هغۀ د حېرانونکى کارونو غږ وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14481, 'Psalms 96:4', 'Psalms', 96, 4, '&nbsp;ځکه چې مالِک خُدائ لوئ دے او د ثناء صِفت لائق دے، د ټولو معبودانو نه د هغۀ زياته يره په کار ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14482, 'Psalms 96:5', 'Psalms', 96, 5, '&nbsp;ځکه چې د قومونو نور ټول معبودان تش بُتان دى، خو مالِک خُدائ آسمانونه جوړ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14483, 'Psalms 96:6', 'Psalms', 96, 6, '&nbsp;شان او شوکت د هغۀ سره ښائى، طاقت او جلال د هغۀ په مقدس کور کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14484, 'Psalms 96:7', 'Psalms', 96, 7, '&nbsp;اے د ټولو قومونو کورَنو، د مالِک خُدائ ثناء او صِفت وکړئ، د مالِک خُدائ لوئى او طاقت بيان کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14485, 'Psalms 96:8', 'Psalms', 96, 8, '&nbsp;د مالِک خُدائ هغه لوئى بيان کړئ کومه چې د هغۀ نوم سره ښائى، د هغۀ دربار ته راشئ او يوه نذرانه راوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14486, 'Psalms 96:9', 'Psalms', 96, 9, '&nbsp;د مالِک خُدائ په خپل قدوسيت او شان شوکت کښې عبادت وکړئ، اے ټولې دُنيا د هغۀ د حضور په وړاندې ولړزېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14487, 'Psalms 96:10', 'Psalms', 96, 10, '&nbsp;په ټولو قومونو کښې دا ووايئ چې، ”مالِک خُدائ بادشاهى کوى. د دُنيا بنيادونه يې مضبوط کړى دى دا به نۀ خوځيږى. او په اِنصاف سره به د خلقو فېصلې وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14488, 'Psalms 96:11', 'Psalms', 96, 11, '&nbsp;پرېږدئ چې آسمانونه خوشحاله شى او زمکه خوشحالى وکړى، سمندر او چې هغې کښې هر څۀ دى هغوئ دې خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14489, 'Psalms 96:12', 'Psalms', 96, 12, '&nbsp;پټى دې هم خوشحالى وکړى او څۀ چې په هغې کښې دى، نو د ځنګل ټولې ونې به د خوشحالۍ سندرې ووائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14490, 'Psalms 96:13', 'Psalms', 96, 13, '&nbsp;دوئ به د مالِک خُدائ په وړاندې سندرې ووائى ځکه چې هغه راروان دے، هغه د دُنيا د عدالت دپاره راځى، هغه به په صداقت سره د دُنيا عدالت وکړى، او د خلقو عدالت به په خپل اِنصاف سره وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14491, 'Psalms 97:1', 'Psalms', 97, 1, '&nbsp;مالِک خُدائ بادشاه دے ټوله دُنيا دې خوشحالى وکړى، او ټولې لرې جزيرې دې خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14492, 'Psalms 97:2', 'Psalms', 97, 2, '&nbsp;او درنې وريځې او تيارې ترې نه راتاوې دى، اِنصاف او صداقت دواړه د هغۀ د تخت بنيادونه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14493, 'Psalms 97:3', 'Psalms', 97, 3, '&nbsp;د هغۀ نه وړاندې اور روان وى، په هر اړخ د هغۀ دشمنان سوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14494, 'Psalms 97:4', 'Psalms', 97, 4, '&nbsp;د هغۀ برېښنا ټوله دُنيا رڼا کوى، زمکه چې دا ګورى نو په لړزان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14495, 'Psalms 97:5', 'Psalms', 97, 5, '&nbsp;د مالِک خُدائ په وړاندې غرونه لکه موم داسې ويلى کيږى، د ټولې دُنيا د مالِک خُدائ په مخکښې داسې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14496, 'Psalms 97:6', 'Psalms', 97, 6, '&nbsp;آسمانونه د هغۀ صداقت بيانوى، او ټول قومونه د هغۀ جلال وينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14497, 'Psalms 97:7', 'Psalms', 97, 7, '&nbsp;هر هغه څوک چې د بُتانو عبادت کوى په شرم به وشرميږى، هغوئ هم څوک چې په بې‌کاره بُتانو نازيږى. اے ټولو معبودانو هغۀ ته سجده وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14498, 'Psalms 97:8', 'Psalms', 97, 8, '&nbsp;د صيون ښار دا اورى او خوشحاليږى او د يهوداه کلى خوشحاله دى، ځکه ستا د عدالت په وجه مالِکه خُدايه دوئ خوشحاله دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14499, 'Psalms 97:9', 'Psalms', 97, 9, '&nbsp;ځکه تۀ، اے مالِکه خُدايه، په ټوله زمکه باندې د ټولو نه اوچت يې، او تۀ په ټولو معبودانو کښې د ټولو نه ښۀ او اوچت يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14500, 'Psalms 97:10', 'Psalms', 97, 10, '&nbsp;څوک چې د مالِک خُدائ سره مينه کوى نو هغوئ دې د بدۍ نه نفرت کوى، هغه د خپلو مقدسينو حفاظت کوى، او هغه يې د بدعملو نه بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');